import GoDFoundation

/// Run a program on the host machine as a step in a config chain.
///
/// Not generated by project setup — hand-authored, like `convert` and the
/// compression ops. Nothing here takes an engine folder: the operation knows
/// nothing about what it is launching, which is the point. It exists so a
/// chain can reach a tool GODDESS doesn't implement — a converter, a patcher,
/// an emulator, a project's own script — without leaving the config file.
enum RunExecutable {

    struct Config: Codable {
        /// The program to run. A `./`-relative path resolves against the
        /// config's `rootFolder`, like every other path field.
        let executablePath: File
        /// Launch arguments, passed one array element per argument and
        /// verbatim: nothing is split on spaces, glob-expanded or resolved
        /// as a path, because there is no shell between here and the child.
        let arguments: [String]?
        /// Lines fed to the program's standard input. Each is written
        /// followed by a newline and the stream is then closed, so a program
        /// reading to EOF sees exactly these lines and stops.
        let standardInput: [String]?
        /// The directory the program runs in. Absent inherits GODDESS's own,
        /// which is wherever the tool was invoked from rather than the
        /// project root — set it when the program resolves its own relative
        /// paths.
        let workingDirectory: Folder?
        /// Where to write what the program printed to standard output.
        /// Absent keeps it in the log only.
        let outputFile: File?
        /// Replace an existing `outputFile`. Absent replaces it.
        let overwrite: Bool?
        /// Stop the chain when the program exits non-zero. Absent stops:
        /// a step that failed shouldn't let the next one run on its output.
        let failOnNonZeroExit: Bool?

        init(
            executablePath: File,
            arguments: [String]? = nil,
            standardInput: [String]? = nil,
            workingDirectory: Folder? = nil,
            outputFile: File? = nil,
            overwrite: Bool? = nil,
            failOnNonZeroExit: Bool? = nil
        ) {
            self.executablePath = executablePath
            self.arguments = arguments
            self.standardInput = standardInput
            self.workingDirectory = workingDirectory
            self.outputFile = outputFile
            self.overwrite = overwrite
            self.failOnNonZeroExit = failOnNonZeroExit
        }
    }
}
